import pandas as pd
import numpy as np

df = pd.read_csv('ckd_lab_data.csv', dtype=str)

def parse_val(s):
    if pd.isna(s):
        return np.nan
    s = s.strip().replace(',', '.')
    try:
        return float(s)
    except:
        return np.nan

# Columns where the range suggests mixed units - look at distribution
problem_cols = ['Serum_Creatinine', 'Hemoglobin', 'Total_Bilirubin', 'Direct_Bilirubin', 
                'Albumin_Serum', 'Total_Protein', 'Magnesium', 'Serum_Calcium',
                'Uric_Acid', 'Glucose', 'Triglycerides', 'Ferritin',
                'Urine_Creatinine', 'Troponin_I', 'Troponin_T',
                'Free_T4', 'pO2_Arterial', 'Lactate', 'Aluminum',
                'Prealbumin', 'Total_Cholesterol', 'LDL_Cholesterol',
                'Vitamin_D_25OH', 'Intact_PTH', 'Phosphorus',
                'Transferrin_Saturation', 'Protein_to_Creatinine_Ratio_Urine',
                'Urine_Protein', 'Non_HDL_Cholesterol']

for col in problem_cols:
    vals = df[col].apply(parse_val).dropna()
    # Show percentiles
    percs = np.percentile(vals, [5, 25, 50, 75, 95])
    print(f'{col}: p5={percs[0]:.2f}, p25={percs[1]:.2f}, p50={percs[2]:.2f}, p75={percs[3]:.2f}, p95={percs[4]:.2f}, min={vals.min():.2f}, max={vals.max():.2f}')
    # Count values in different ranges
    if col == 'Serum_Creatinine':
        print(f'  <30: {(vals < 30).sum()}, 30-200: {((vals >= 30) & (vals < 200)).sum()}, >=200: {(vals >= 200).sum()}')
    elif col == 'Hemoglobin':
        print(f'  <20: {(vals < 20).sum()}, 20-100: {((vals >= 20) & (vals < 100)).sum()}, >=100: {(vals >= 100).sum()}')
    elif col == 'Total_Bilirubin':
        print(f'  <5: {(vals < 5).sum()}, 5-20: {((vals >= 5) & (vals < 20)).sum()}, >=20: {(vals >= 20).sum()}')
    elif col == 'Direct_Bilirubin':
        print(f'  <2: {(vals < 2).sum()}, 2-20: {((vals >= 2) & (vals < 20)).sum()}, >=20: {(vals >= 20).sum()}')
    elif col == 'Albumin_Serum':
        print(f'  <6: {(vals < 6).sum()}, 6-20: {((vals >= 6) & (vals < 20)).sum()}, >=20: {(vals >= 20).sum()}')
    elif col == 'Total_Protein':
        print(f'  <12: {(vals < 12).sum()}, 12-50: {((vals >= 12) & (vals < 50)).sum()}, >=50: {(vals >= 50).sum()}')
    elif col == 'Uric_Acid':
        print(f'  <15: {(vals < 15).sum()}, 15-100: {((vals >= 15) & (vals < 100)).sum()}, >=100: {(vals >= 100).sum()}')
    elif col == 'Glucose':
        print(f'  <500: {(vals < 500).sum()}, >=500: {(vals >= 500).sum()}')
